package com.specdriven.regression.runner;
import static org.assertj.core.api.Assertions.*;
import java.io.*;import java.nio.file.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class RunnerDurabilityTest {
 @TempDir Path temp;
 BoundedEvidenceCollectorTest fixture(boolean canonical)throws Exception{var f=new BoundedEvidenceCollectorTest();f.temp=temp;f.setup();if(canonical)f.existingCanonicalFixture(false);else f.add("canonical/provider-evidence/grpc-client/proof.json","evidence","{\"public\":true}",true);Files.write(f.spec,BoundedEvidenceCollectorTest.JSON.writeValueAsBytes(f.manifest));return f;}
 static class Port implements RunnerDurability {
  final Path root;final List<String> events=new ArrayList<>();String failDir,failFile,alterRead;boolean failMarkerDirectory,alterMarkerFinalRead;
  Port(Path root){this.root=root;}
  String ref(Path p){return root.relativize(p).toString().replace('\\','/');}
  public void forceDirectory(Path p)throws IOException{String name=ref(p);events.add("dir:"+name);if(name.equals(failDir)||(failMarkerDirectory&&events.contains("file:SAVE.complete")))throw new IOException("public unsupported directory force");RunnerDurability.SYSTEM.forceDirectory(p);}
  public void forceFile(Path p)throws IOException{String name=ref(p);events.add("file:"+name);if(name.equals(failFile))throw new IOException("public file force failure");RunnerDurability.SYSTEM.forceFile(p);}
  public byte[] readSaved(Path base,String path,long maximum)throws IOException{events.add("read:"+path);if(path.equals(alterRead)||(alterMarkerFinalRead&&path.equals("SAVE.complete")&&Collections.frequency(events,"read:"+path)>=2))return "public changed readback".getBytes();return RunnerDurability.SYSTEM.readSaved(base,path,maximum);}
 }
 @Test void everyNestedDirectoryEntryForcedBeforeCompleteSave()throws Exception{var f=fixture(false);var port=new Port(f.out);var r=new BoundedEvidenceCollector(port).collect(f.spec,BoundedEvidenceCollectorTest.sha(Files.readAllBytes(f.spec)),f.source,f.out);assertThat(r.complete()).isTrue();assertThat(port.events).contains("dir:canonical","dir:canonical/provider-evidence","dir:canonical/provider-evidence/grpc-client");int marker=port.events.indexOf("file:SAVE.complete");assertThat(marker).isGreaterThan(port.events.indexOf("dir:canonical/provider-evidence"));}
 @Test void unsupportedIntermediateDirectoryForceCannotProduceCompleteSave()throws Exception{var f=fixture(false);var port=new Port(f.out);port.failDir="canonical/provider-evidence";assertThatThrownBy(()->new BoundedEvidenceCollector(port).collect(f.spec,BoundedEvidenceCollectorTest.sha(Files.readAllBytes(f.spec)),f.source,f.out)).isInstanceOf(IOException.class);assertThat(Files.exists(f.out.resolve("SAVE.complete"))).isFalse();assertThat(Files.exists(f.source.resolve("canonical/provider-evidence/grpc-client/proof.json"))).isTrue();}
 @Test void derivedCoverageFilesAreForcedAndRecheckedBeforeMarker()throws Exception{var f=fixture(true);var port=new Port(f.out);var r=new BoundedEvidenceCollector(port).collect(f.spec,BoundedEvidenceCollectorTest.sha(Files.readAllBytes(f.spec)),f.source,f.out);assertThat(r.complete()).isTrue();for(String path:List.of("controller-derived/coverage/coverage.json","controller-derived/coverage/coverage.md")){assertThat(port.events).contains("file:"+path,"read:"+path);assertThat(port.events.indexOf("file:"+path)).isLessThan(port.events.indexOf("file:SAVE.complete"));}}
 @Test void derivedFileForceFailurePreventsCompleteSave()throws Exception{var f=fixture(true);var port=new Port(f.out);port.failFile="controller-derived/coverage/coverage.json";assertThatThrownBy(()->new BoundedEvidenceCollector(port).collect(f.spec,BoundedEvidenceCollectorTest.sha(Files.readAllBytes(f.spec)),f.source,f.out)).isInstanceOf(IOException.class);assertThat(Files.exists(f.out.resolve("SAVE.complete"))).isFalse();}
 @Test void derivedFileReadbackMismatchPreventsCompleteSave()throws Exception{var f=fixture(true);var port=new Port(f.out);port.alterRead="controller-derived/coverage/coverage.md";assertThatThrownBy(()->new BoundedEvidenceCollector(port).collect(f.spec,BoundedEvidenceCollectorTest.sha(Files.readAllBytes(f.spec)),f.source,f.out)).isInstanceOfAny(IOException.class,IllegalArgumentException.class);assertThat(Files.exists(f.out.resolve("SAVE.complete"))).isFalse();}
 @Test void completionMarkerForceFailureRemovesMarkerAndRetainsSource()throws Exception{var f=fixture(false);var port=new Port(f.out);port.failFile="SAVE.complete";assertThatThrownBy(()->new BoundedEvidenceCollector(port).collect(f.spec,BoundedEvidenceCollectorTest.sha(Files.readAllBytes(f.spec)),f.source,f.out)).isInstanceOf(IOException.class);assertThat(Files.exists(f.out.resolve("SAVE.complete"))).isFalse();assertThat(Files.exists(f.source.resolve("canonical/provider-evidence/grpc-client/proof.json"))).isTrue();}
 @Test void completionMarkerFinalReadbackFailureRemovesMarkerAndRetainsSource()throws Exception{var f=fixture(false);var port=new Port(f.out);port.alterMarkerFinalRead=true;assertThatThrownBy(()->new BoundedEvidenceCollector(port).collect(f.spec,BoundedEvidenceCollectorTest.sha(Files.readAllBytes(f.spec)),f.source,f.out)).isInstanceOf(IllegalArgumentException.class);assertThat(port.events).contains("file:SAVE.complete");assertThat(Files.exists(f.out.resolve("SAVE.complete"))).isFalse();assertThat(Files.exists(f.source.resolve("canonical/provider-evidence/grpc-client/proof.json"))).isTrue();}
 @Test void completionMarkerDirectoryForceFailureRemovesMarkerEvenWhenInvalidationSyncUnsupported()throws Exception{var f=fixture(false);var port=new Port(f.out);port.failMarkerDirectory=true;assertThatThrownBy(()->new BoundedEvidenceCollector(port).collect(f.spec,BoundedEvidenceCollectorTest.sha(Files.readAllBytes(f.spec)),f.source,f.out)).isInstanceOf(IOException.class);assertThat(Files.exists(f.out.resolve("SAVE.complete"))).isFalse();assertThat(Files.exists(f.source.resolve("canonical/provider-evidence/grpc-client/proof.json"))).isTrue();}
}
